function relocateTarget(u){if(!targetIndexed)return;const cell=targetCell(u);if(cell===u._targetCell)return;const previous=targetBins[u._targetCell];previous.splice(previous.indexOf(u),1);targetBins[cell].push(u);u._targetCell=cell}
function chooseEnemyTarget(u){
 const detection=u.kind==='hero'?430:u.kind==='tower'?u.range:320;
 let target=null,best=Infinity;
 const consider=t=>{if(t.hp<=0||t.team===u.team||(t.team===2&&!(u.kind==='hero'&&u.kit===4)))return;
  const dx=u.x-t.x,dy=u.y-t.y;if(dx*dx+dy*dy>detection*detection)return;
  const d=dist(u,t);if(d>detection)return;let priority=d;
  if(u.kind==='tower'){if(u.aggro===t)priority=-200;else if(['minion','siege'].includes(t.kind))priority-=300}
  else if(u.kind==='hero'&&u.kit!==4&&t.kind==='hero')priority+=130;
  if(priority<best||(targetIndexed&&target&&priority===best&&t._targetOrder<target._targetOrder)){best=priority;target=t}
 };
 if(!targetIndexed){for(const t of units)consider(t);return target}
 const left=clamp(Math.floor((u.x-detection)/TARGET_CELL),0,TARGET_SIDE-1),right=clamp(Math.floor((u.x+detection)/TARGET_CELL),0,TARGET_SIDE-1);
 const top=clamp(Math.floor((u.y-detection)/TARGET_CELL),0,TARGET_SIDE-1),bottom=clamp(Math.floor((u.y+detection)/TARGET_CELL),0,TARGET_SIDE-1);
 for(let y=top;y<=bottom;y++)for(let x=left;x<=right;x++)for(const t of targetBins[y*TARGET_SIDE+x])consider(t);
 return target;
}
function updateUnit(u,dt){tickMinionEffects(u,dt);u.cd-=dt;u.moving=false;for(const key of ['flash','slow','shield','buff','attackAnim'])u[key]=Math.max(0,(u[key]||0)-dt);if(u.skills)for(let i=0;i<u.skills.length;i++)u.skills[i]=Math.max(0,u.skills[i]-dt);if(u.hp<=0){if(u.respawn>0){u.respawn-=dt;if(u.respawn<=0){u.hp=u.maxHp;u.pending=null;if(u.kind==='hero'){Object.assign(u,{x:bases[u.team].x+80,y:bases[u.team].y-80});u.mana=u.maxMana;u.navTimer=0;u.path=[]}else{Object.assign(u,u.home);u.aggro=null}}}return}
  if(u.kind==='hero'){u.mana=Math.min(u.maxMana,u.mana+dt*8);u.hp=Math.min(u.maxHp,u.hp+dt*(dist(u,bases[u.team])<210?120:1.5));if(u.recall>0){u.recall-=dt;fx(u.x,u.y,35+Math.sin(clock*5)*10,'#86d8ea','ring',.12);if(u.recall<=0){Object.assign(u,{x:bases[u.team].x+90,y:bases[u.team].y-90});u.order=null;u.path=[];u.hp=u.maxHp;u.mana=u.maxMana;if(u===selected)message('Returned to the fountain. Open the shop to spend bells.')}return}}
  if(u.dash){const s=Math.min(u.dash.left,900*dt),x=u.x+u.dash.x*s,y=u.y+u.dash.y*s;if(!blocked(x,y,u.radius*.8)){u.x=x;u.y=y;u.dash.left-=s;burst(u.x,u.y,kits[u.kit].color,2)}else u.dash.left=0;if(u.dash.left<=0)u.dash=null;return}
  if(u.pending){u.pending.time-=dt;if(u.pending.time<=0){releaseAttack(u,u.pending.target);u.pending=null}return}if(u.kind==='barracks')return;if(u.species==='dormouse'&&u.cd<=0&&tryMinionHeal(u))return;
  const mobile=['hero','minion','siege'].includes(u.kind),player=u===selected;let target=null;
  if(player&&u.order?.point&&!u.order.attack){move(u,u.order.point,dt,u.slow?.55:1);if(dist(u,u.order.point)<16)u.order=null;return}
  if(player&&u.order?.target){if(u.order.target.hp>0)target=u.order.target;else u.order=null}
  if(!target&&u.team===2){if(u.aggro?.hp>0&&dist(u,u.aggro)<450&&dist(u,u.home)<300)target=u.aggro;else{u.aggro=null;u.hp=Math.min(u.maxHp,u.hp+dt*40);if(dist(u,u.home)>10)move(u,u.home,dt)}}
  if(!target&&u.team!==2&&(!player||u.order?.attack))target=chooseEnemyTarget(u);
  if(target){if(dist(u,target)<=u.range+target.radius){if(u.cd<=0)attack(u,target);if(u.kind==='hero'&&!player&&target.kind==='hero'&&Math.random()<dt*.15)cast(u,Math.random()<.1?3:0,target)}else if(mobile||u.team===2)move(u,target,dt,u.slow?.55:1)}else if(mobile){if(player){if(u.order?.point){move(u,u.order.point,dt);if(dist(u,u.order.point)<16)u.order=null}}else if(u.kind==='hero'&&u.kit===4){const camp=units.filter(t=>t.team===2&&t.hp>0).sort((a,b)=>dist(u,a)-dist(u,b))[0];if(camp)move(u,camp,dt)}else{const progress=nearestProgress(u,u.lane);const limit=u.kind==='hero'?(u.team?.48:.52):(u.team?0:1);const next=clamp(progress+(u.team?-1:1)*.025,Math.min(progress,limit),Math.max(progress,limit));move(u,pointOnLane(u.lane,next),dt)}}
  if(u.kind==='hero'&&!player&&u.hp/u.maxHp<.22){u.order=null;move(u,pointOnLane(u.lane,u.team?.68:.32),dt)}
}
update=function(dt){if(winner!==null)return;clock+=dt;flashCd=Math.max(0,flashCd-dt);shake=Math.max(0,shake-dt*12);if(clock>=nextWave){spawnWave();nextWave+=25}
 prepareTargeting();for(const u of units){updateUnit(u,dt);relocateTarget(u)}
 separate();for(const p of projectiles){if(p.target.hp<=0){p.done=true;continue}p.trail.push({x:p.x,y:p.y});if(p.trail.length>5)p.trail.shift();const d=dist(p,p.target);if(d<p.speed*dt){minionImpact(p);p.done=true}else{p.x+=(p.target.x-p.x)/d*p.speed*dt;p.y+=(p.target.y-p.y)/d*p.speed*dt}}
 projectiles=projectiles.filter(p=>!p.done);for(const p of skillshots){p.trail.push({x:p.x,y:p.y});if(p.trail.length>8)p.trail.shift();const step=p.speed*dt;p.x+=p.dx*step;p.y+=p.dy*step;p.left-=step;if(blocked(p.x,p.y,5))p.left=0;const hit=units.find(t=>t.hp>0&&t.team!==p.source.team&&dist(p,t)<t.radius+p.radius);if(hit){hurt(hit,p.damage,p.source);hit.slow=1.5;p.left=0;fx(p.x,p.y,45,p.color);burst(p.x,p.y,p.color,15)}}skillshots=skillshots.filter(p=>p.left>0);
 for(const e of effects){e.life-=dt;if(e.type==='telegraph'&&e.life<=0){for(const t of units)if(t.hp>0&&t.team!==e.source.team&&dist(t,e)<e.r+t.radius){hurt(t,e.damage,e.source);t.slow=1.5}fx(e.x,e.y,e.r,e.color,'blast',.5);burst(e.x,e.y,e.color,35);if(e.source===selected)shake=5}}
effects=effects.filter(e=>e.life>0);for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.94;p.vy*=.94}particles=particles.filter(p=>p.life>0);floats.forEach(f=>{f.life-=dt;f.y-=dt*45});floats=floats.filter(f=>f.life>0);decals.forEach(d=>d.life-=dt);decals=decals.filter(d=>d.life>0);units=units.filter(u=>u.hp>0||!['minion','siege'].includes(u.kind)||(u.species&&(u.dead||0)<.9));};
function ellipse(x,y,rx,ry,color,angle=0){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,angle,0,TAU);ctx.fill()}
function polygon(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function stone(x,y,r){ellipse(x+8,y+13,r*1.15,r*.65,'#102c2c66');polygon([[x-r,y+6],[x-r*.8,y-r*.65],[x-r*.2,y-r],[x+r*.65,y-r*.8],[x+r,y],[x+r*.6,y+r*.6],[x-r*.65,y+r*.6]],'#596a67','#334c49');polygon([[x-r*.8,y-r*.65],[x-r*.2,y-r],[x+r*.65,y-r*.8],[x+r*.45,y-r*.2],[x-r*.4,y]],'#8b9b87');polygon([[x-r*.4,y],[x+r*.45,y-r*.2],[x+r,y],[x+r*.6,y+r*.6],[x-r*.65,y+r*.6]],'#6b7e70');path([[x-r*.65,y+r*.3],[x-r*.15,y+r*.45]],4,'#88a465')}
function tree(t){ellipse(t.x+13,t.y+22,t.r*1.1,t.r*.65,'#08282366');path([[t.x,t.y+20],[t.x-2,t.y-20]],10,'#655140');const layers=[[-11,3,.9,'#224c3e'],[10,-5,.86,'#2d6146'],[-3,-20,.83,'#3b7650'],[-9,-27,.58,'#4f885a'],[-14,-34,.28,'#75a064']];for(const [dx,dy,r,c] of layers){ellipse(t.x+dx,t.y+dy,t.r*r,t.r*r*.8,c)}for(let i=0;i<3;i++)ellipse(t.x-10+i*10,t.y-27-i*3,4,2,'#a4bd7433')}
function paintTerrain(){ctx.fillStyle='#294b3c';ctx.fillRect(0,0,W,H);const random=rng(58211);for(let i=0;i<750;i++){const x=random()*W,y=random()*H,r=25+random()*100;ellipse(x,y,r,r*.65,['#305440','#375c43','#3c6347','#2d513f'][i%4])}
 for(const l of lanes){path(l,228,'#203f32');path(l,205,'#64805a');path(l,178,'#7c8b65');path(l,145,'#929674');path(l,116,'#a1a17e')}
 // Travel routes around the jungle's solid islands.
 for(const line of [[[450,2320],[770,2120],[1030,1840],[1300,1530]],[[640,2300],[1060,2430],[1450,2330],[1800,2080]],[[440,830],[780,1190],[1040,1240],[1450,1410]]]){path(line,98,'#365c42');path(line,70,'#5b7753');const mirrored=line.map(p=>[W-p[0],H-p[1]]);path(mirrored,98,'#365c42');path(mirrored,70,'#5b7753')}
 path(river,255,'#244b42');path(river,218,'#728d69');path(river,190,'#4b8078');path(river,148,'#397f87');path(river,104,'#408d99');
 for(let i=0;i<180;i++){const segment=i%(river.length-1),a=river[segment],b=river[segment+1],f=random(),x=a[0]+(b[0]-a[0])*f+(random()-.5)*100,y=a[1]+(b[1]-a[1])*f+(random()-.5)*100;path([[x,y],[x+18,y+12]],2,'#86c6ba35')}
 for(let i=0;i<2200;i++){const x=120+random()*2960,y=120+random()*2960;if(nearLane({x,y},80)){ctx.save();ctx.translate(x,y);ctx.rotate(-.78);ctx.fillStyle=i%3?'#d1c8a126':'#4e60482a';ctx.fillRect(-9,-4,18+random()*13,8+random()*5);ctx.restore()}else if(!river.slice(1).some((p,j)=>segmentDistance({x,y},river[j],p)<120)){path([[x,y],[x-3,y-7],[x+1,y-4],[x+4,y-10]],1,'#7d9a5938')}}
 for(const [i,b] of bases.entries()){ellipse(b.x,b.y,270,270,'#243e39');ellipse(b.x,b.y,244,244,'#6c8174');ellipse(b.x,b.y,224,224,'#8d9b88');ellipse(b.x,b.y,199,199,'#768c7c');for(let a=0;a<TAU;a+=.24){const x=b.x+Math.cos(a)*215,y=b.y+Math.sin(a)*215;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#c2c3a3';ctx.fillRect(-12,-7,25,14);ctx.restore()}const fountain={x:b.x+(i?100:-100),y:b.y+(i?-100:100)};ellipse(fountain.x,fountain.y,55,40,'#87988e');ellipse(fountain.x,fountain.y,43,28,i?'#ac817c':'#559ea1');text('FOUNTAIN',fountain.x,fountain.y+60,12,'#d8dfc7')}
 for(const u of units.filter(u=>u.team===2)){ellipse(u.home.x,u.home.y,u.kind==='boss'?155:96,u.kind==='boss'?145:79,'#274b3e');ellipse(u.home.x,u.home.y,u.kind==='boss'?128:80,u.kind==='boss'?118:67,u.name==='Moana'?'#457c7d':'#6b7960');if(u.kind==='boss'){for(let a=-2.8;a<.45;a+=.25){const x=u.x+Math.cos(a)*150,y=u.y+Math.sin(a)*140;stone(x,y,28)}text(u.name==='Dragex'?'MOUNT YOKAI':'MORANE BAY',u.x,u.y+190,19,'#e1d6ab')}}
 for(const o of obstacles.filter(o=>!o.structure)){ellipse(o.x+10,o.y+18,o.r+8,o.r*.8,'#173c30');ellipse(o.x,o.y,o.r,o.r*.8,'#46634d')}
 for(const r of rocks)stone(r.x,r.y,r.r);
 // Scenery follows the same island silhouettes as collision geometry.
 for(const t of trees)tree(t);
 for(const b of brush){ellipse(b.x,b.y,b.rx,b.ry,'#244c39');for(let i=0;i<75;i++){const x=b.x+(random()-.5)*b.rx*1.8,y=b.y+(random()-.5)*b.ry*1.5;path([[x-5,y+7],[x-3,y-11],[x+1,y],[x+7,y-15],[x+5,y+7]],2,i%3?'#7ca665':'#b0ba71')}}
 for(let i=0;i<200;i++){const x=120+random()*2960,y=120+random()*2960;if(nearLane({x,y},100)||blocked(x,y)||river.slice(1).some((p,j)=>segmentDistance({x,y},river[j],p)<100))continue;for(let a=0;a<TAU;a+=TAU/5)circle(x+Math.cos(a)*3,y+Math.sin(a)*3,2,i%2?'#c19ba3':'#d7c97e');circle(x,y,2,'#f2d790')}
}
terrain=function(){if(!terrainCache){terrainCache=document.createElement('canvas');terrainCache.width=W;terrainCache.height=H;const live=ctx;ctx=terrainCache.getContext('2d');paintTerrain();ctx=live}ctx.drawImage(terrainCache,0,0)};
