 path([[0,18],[Math.sin(clock*5+u.id)*9,34],[Math.sin(clock*5+u.id)*15,45]],k===1?15:6,k===1?'#cb7145':c);if(k===1)ellipse(Math.sin(clock*5+u.id)*15,45,7,10,'#efe1bb');if(k===0)ellipse(Math.sin(clock*5+u.id)*15,45,6,7,'#986039');
