function structure(u){const color=u.team?'#d7886d':'#7ccfc1',r=u.radius;ellipse(u.x+6,u.y+12,r*1.4,r*.7,'#09272d70');ellipse(u.x,u.y,r*1.2,r*.75,'#7d9281');if(u.kind==='castle'){for(const side of [-1,1]){const x=u.x+side*45;polygon([[x-17,u.y+18],[x-17,u.y-67],[x+17,u.y-67],[x+17,u.y+18]],'#a5ad95','#4b665d');polygon([[x-26,u.y-67],[x,u.y-100],[x+26,u.y-67]],u.team?'#a95349':'#387f87','#3f5850');path([[x,u.y-98],[x,u.y-128]],3,'#c4b47d');polygon([[x,u.y-128],[x+27,u.y-118],[x,u.y-107]],color)}polygon([[u.x-39,u.y+20],[u.x-39,u.y-58],[u.x+39,u.y-58],[u.x+39,u.y+20]],'#c9c5a3','#637666');polygon([[u.x-46,u.y-58],[u.x,u.y-83],[u.x+46,u.y-58]],u.team?'#955747':'#438486');ellipse(u.x,u.y+5,12,20,'#344c44');text('CASTLE',u.x,u.y+65,13)}else if(u.kind==='tower'){polygon([[u.x-26,u.y+13],[u.x-22,u.y-55],[u.x+22,u.y-55],[u.x+27,u.y+13]],'#a4b19b','#496158');polygon([[u.x-22,u.y-55],[u.x-6,u.y-60],[u.x-5,u.y+10],[u.x-26,u.y+13]],'#d1d3b2');ellipse(u.x,u.y-58,31,17,'#697e70');ellipse(u.x,u.y-61,25,13,'#bac3a6');for(const dx of [-24,-8,8,24]){ctx.fillStyle='#cbd0af';ctx.fillRect(u.x+dx-5,u.y-82,10,24)}path([[u.x,u.y-78],[u.x,u.y-102]],3,'#d9c286');polygon([[u.x,u.y-102],[u.x+25,u.y-93],[u.x,u.y-82]],color);polygon([[u.x-7,u.y-37],[u.x,u.y-48],[u.x+7,u.y-37],[u.x,u.y-24]],color);ellipse(u.x,u.y+3,9,13,'#334e44')}else{polygon([[u.x-31,u.y+11],[u.x-31,u.y-32],[u.x+31,u.y-32],[u.x+31,u.y+11]],'#a4b198','#556f60');polygon([[u.x-39,u.y-32],[u.x,u.y-59],[u.x+39,u.y-32]],color);ellipse(u.x,u.y,11,14,'#2e4c42')}
}
drawUnit=function(u){if(u.hp<=0){if(['tower','castle','barracks'].includes(u.kind)){stone(u.x,u.y,25);stone(u.x-20,u.y+10,15)}return}const color=u===selected?'#91e290':u.team===0?'#72c7da':u.team===1?'#f08379':'#e4ba70';if(u===selected){ctx.strokeStyle='#a2e3a1';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(u.x,u.y+4,30,20,0,0,TAU);ctx.stroke()}if(hover===u||selected?.order?.target===u){ctx.strokeStyle=u.team===1?'#fb8a6e':'#e3c385';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(u.x,u.y+4,u.radius+9,(u.radius+9)*.7,0,0,TAU);ctx.stroke()}
 if(u.kind==='hero')animal(u);else if(['tower','castle','barracks'].includes(u.kind))structure(u);else if(u.team===2)monster(u);else if(u.species){if(!window.Minion3D?.has?.(u.species))drawMinionFallback(u)}else{const c=u.team?'#ba6960':'#5c9cba',walk=u.moving?Math.sin((u.walk||0)*2)*3:0;ellipse(u.x+2,u.y+6,u.radius,8,'#08252f80');ctx.save();ctx.translate(u.x,u.y-4-Math.abs(walk)*.4);ctx.rotate((u.facing||0)+Math.PI/2);ellipse(-7,10+walk,5,7,'#6c765d');ellipse(7,10-walk,5,7,'#6c765d');ellipse(0,2,u.radius,u.radius*1.1,c);ellipse(0,-9,9,9,'#d6c5a3');ellipse(0,-13,11,6,c);circle(-3,-10,1.5,'#344239');circle(3,-10,1.5,'#344239');if(u.ranged){path([[12,-4],[19,-22]],3,'#a3824e');circle(19,-22,4,'#b4e9e0')}else{path([[13,3],[17,-18]],3,'#cdc7a2');polygon([[13,-18],[17,-26],[21,-18]],'#dedcbc')}circle(-9,4,4,'#dfb449');circle(-9,3,2,'#ffdd79');if(u.kind==='siege'){ellipse(0,4,22,24,'#92a36d');path([[0,-3],[0,-29]],12,'#3c5551');circle(0,-29,6,'#1e3d3c')}ctx.restore()}
 if(u.shield>0){ctx.strokeStyle='#d3eba190';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(u.x,u.y-12,u.radius+12,u.radius+16,0,0,TAU);ctx.stroke()}if(u.flash>0)ellipse(u.x,u.y-10,u.radius*.7,u.radius*.7,'#ffffff75');
 const bar=u.kind==='hero'?76:u.kind==='boss'?120:u.kind==='tower'?80:u.radius*2+8,y=u.y-(u.kind==='tower'?115:u.kind==='castle'?150:u.radius+30);ctx.fillStyle='#0c242b';ctx.fillRect(u.x-bar/2-2,y-2,bar+4,10);ctx.fillStyle='#654c45';ctx.fillRect(u.x-bar/2,y,bar,6);ctx.fillStyle=color;ctx.fillRect(u.x-bar/2,y,bar*u.hp/u.maxHp,6);if(u.kind==='hero'){for(let i=1;i<Math.ceil(u.maxHp/250);i++){ctx.fillStyle='#13303199';ctx.fillRect(u.x-bar/2+bar*i*250/u.maxHp,y,1,6)}ctx.fillStyle='#192d45';ctx.fillRect(u.x-bar/2,y+8,bar,3);ctx.fillStyle='#62b6db';ctx.fillRect(u.x-bar/2,y+8,bar*u.mana/u.maxMana,3);if(u===selected){ctx.fillStyle='#16302d';ctx.fillRect(u.x-bar/2,y+13,bar,2);ctx.fillStyle='#e3d296';ctx.fillRect(u.x-bar/2,y+13,bar*clamp(1-u.cd/.78,0,1),2);}text(`${u.name}  ${u.level}`,u.x,y-8,12,u===selected?'#d4f6c6':'#e6e6cf')}else if(u.team===2)text(u.name,u.x,y-9,12,'#e5d6aa');
 if(u.team===1&&['minion','siege'].includes(u.kind)&&selected&&u.hp<=selected.damage){ctx.strokeStyle='#ffdb74';ctx.lineWidth=2;ctx.strokeRect(u.x-bar/2-2,y-2,bar+4,10)}};
drawMini=function(){mc.fillStyle='#254c39';mc.fillRect(0,0,180,140);mc.strokeStyle='#6fa9b0';mc.lineWidth=7;mc.beginPath();river.forEach((p,i)=>i?mc.lineTo(p[0]/W*180,p[1]/H*140):mc.moveTo(p[0]/W*180,p[1]/H*140));mc.stroke();mc.strokeStyle='#b7b383';mc.lineWidth=3;for(const l of lanes){mc.beginPath();l.forEach((p,i)=>i?mc.lineTo(p[0]/W*180,p[1]/H*140):mc.moveTo(p[0]/W*180,p[1]/H*140));mc.stroke()}for(const o of obstacles.filter(o=>!o.structure)){mc.fillStyle='#17392f';mc.beginPath();mc.ellipse(o.x/W*180,o.y/H*140,o.r/W*180,o.r/H*140,0,0,TAU);mc.fill()}for(const u of units){if(u.hp<=0)continue;mc.fillStyle=u===selected?'#e8ec9a':u.team===0?'#78d4db':u.team===1?'#f18c7d':'#dfc894';mc.beginPath();mc.arc(u.x/W*180,u.y/H*140,u.kind==='hero'?3:u.kind==='castle'?4:1.5,0,TAU);mc.fill()}mc.strokeStyle='#f1e6bb90';mc.lineWidth=1;mc.strokeRect((camera.x-canvas.clientWidth/camera.zoom/2)/W*180,(camera.y-canvas.clientHeight/(camera.zoom*.83)/2)/H*140,canvas.clientWidth/camera.zoom/W*180,canvas.clientHeight/(camera.zoom*.83)/H*140)};
draw=function(){const width=canvas.clientWidth,height=canvas.clientHeight,dpr=Math.min(window.devicePixelRatio||1,2);if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=width*dpr;canvas.height=height*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);ctx.fillStyle='#132d29';ctx.fillRect(0,0,width,height);ctx.translate(width/2+(Math.random()-.5)*shake,height/2+(Math.random()-.5)*shake);ctx.scale(camera.zoom,camera.zoom*.83);ctx.translate(-camera.x,-camera.y);terrain();
 // Subtle moving river glints and drifting forest motes.
 for(let i=0;i<24;i++){const index=i%(river.length-1),a=river[index],b=river[index+1],f=(clock*.06+i*.137)%1,x=a[0]+(b[0]-a[0])*f,y=a[1]+(b[1]-a[1])*f;ellipse(x,y,8,2,'#b4e5d355',.7)}
 for(const d of decals){ctx.globalAlpha=Math.min(1,d.life/3);ellipse(d.x,d.y,d.r,d.r*.6,d.color+'50');ctx.globalAlpha=1}
 // Hovering a turret reveals its danger radius before a dive.
 for(const u of units.filter(u=>u.kind==='tower'&&u.team===1&&u.hp>0&&selected&&dist(u,selected)<u.range+120)){ctx.strokeStyle=dist(u,selected)<u.range?'#ed8c6666':'#e4b96b44';ctx.lineWidth=2;ctx.beginPath();ctx.arc(u.x,u.y,u.range,0,TAU);ctx.stroke()}
 if(selected&&attackMove){ctx.strokeStyle='#a9dadc55';ctx.lineWidth=1;ctx.beginPath();ctx.arc(selected.x,selected.y,selected.range,0,TAU);ctx.stroke()}
 // Keep a generous margin for wings, health bars and castle roofs.
 const halfWidth=width/camera.zoom/2+200,halfHeight=height/(camera.zoom*.83)/2+200;
 visibleUnits.length=0;
 for(const u of units)if(Math.abs(u.x-camera.x)<=halfWidth&&Math.abs(u.y-camera.y)<=halfHeight)visibleUnits.push(u);
 visibleUnits.sort((a,b)=>a.y-b.y).forEach(drawUnit);
 for(const p of [...projectiles,...skillshots]){if(p.source?.species&&window.Minion3D?.has?.(p.source.species))continue;if(p.trail?.length>1){path(p.trail.map(t=>[t.x,t.y]),p.radius?8:3,p.color+'80')}if(!drawMinionProjectile(p)){ellipse(p.x,p.y,p.radius?10:5,p.radius?7:3,p.color);circle(p.x,p.y,p.radius?5:3,'#fff8da')}}
 for(const e of effects){const f=clamp(e.life/e.max,0,1);ctx.save();ctx.globalAlpha=f;ctx.strokeStyle=e.color;ctx.fillStyle=e.color+'25';ctx.lineWidth=3;if(e.type==='slash'){ctx.translate(e.x,e.y);ctx.rotate(e.angle||0);ctx.beginPath();ctx.arc(0,0,e.r*(1-f*.15),-.7,.7);ctx.lineWidth=8;ctx.stroke();ctx.beginPath();ctx.arc(0,0,e.r*.8,-.6,.5);ctx.lineWidth=3;ctx.stroke()}else if(e.type==='telegraph'){ctx.globalAlpha=.7;ctx.setLineDash([12,8]);ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,TAU);ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1-f),0,TAU);ctx.stroke()}else{ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1-f*.4),0,TAU);ctx.fill();ctx.stroke();if(e.type==='blast'){ctx.lineWidth=8;ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1-f),0,TAU);ctx.stroke()}}ctx.restore()}
 for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*3);circle(p.x,p.y,p.r,p.color)}ctx.globalAlpha=1;
 for(const f of floats){ctx.globalAlpha=Math.min(1,f.life*3);ctx.font=`700 ${f.size}px "DM Sans",sans-serif`;ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#12262a';ctx.strokeText(f.label,f.x,f.y);ctx.fillStyle=f.color;ctx.fillText(f.label,f.x,f.y)}ctx.globalAlpha=1;
 if(selected?.order?.point){const p=selected.order.point;const r=9+Math.sin(clock*8)*2;for(let i=0;i<4;i++){const a=i*Math.PI/2;path([[p.x+Math.cos(a)*r,p.y+Math.sin(a)*r],[p.x+Math.cos(a+.3)*(r+6),p.y+Math.sin(a+.3)*(r+6)]],2,'#9ce6be')}}
drawMini();if(selected?.hp<=0){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#15263855';ctx.fillRect(0,0,width,height);text(`RETURNING IN ${Math.ceil(selected.respawn)}`,width/2,height/2,24)}if(winner!==null){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#102421bf';ctx.fillRect(0,0,width,height);text(`${winner===0?'VERDANT':'CRIMSON'} KINGDOM VICTORIOUS`,width/2,height/2,28);text('Start a new battle to conquer again',width/2,height/2+38,16)}};
function chooseHero(i){closeShop();selected=units.find(u=>u.team===0&&u.kind==='hero'&&u.kit===i);follow=true;camera.zoom=1.1;camera.x=selected.x;camera.y=selected.y;document.body.classList.remove('roster-open');renderRoster();updateUI()}
renderRoster=function(){document.getElementById('roster').innerHTML=kits.map((k,i)=>`<button class="pick ${selected?.kit===i?'active':''}" data-kit="${i}"><span class="portrait">${k.icon}</span><span><strong>${k.name}</strong><small>${k.species}</small></span></button>`).join('');document.querySelectorAll('[data-kit]').forEach(b=>b.onclick=()=>chooseHero(+b.dataset.kit))};
function skillDescription(k,i){if(i===2)return k===2?'Heal 300 · shield':'Dash 220 · blocked by terrain';if(i===0)return [0,2].includes(k)?'150 damage · close area':'170 damage · aimed projectile';return i===1?'110 damage · nearby enemies':'330 damage · delayed area strike'}
updateUI=function(){document.getElementById('score').innerHTML=`VERDANT <b>${kills[0]} : ${kills[1]}</b> CRIMSON · ${Math.floor(clock/60)}:${String(Math.floor(clock%60)).padStart(2,'0')}`;document.getElementById('status').textContent=winner!==null?'Conquest complete':selected?(selected.hp<=0?`Respawning in ${Math.ceil(selected.respawn)}s`:`${follow?'Camera locked · Y to unlock':'Camera unlocked · Space to center'} · ${units.filter(u=>u.kind==='minion').length} minions`):'Spectating';const u=selected;if(window.Minion3D)document.getElementById('status').textContent+=window.Minion3D.errors.length?' · simplified fallback':` · 3D ${window.Minion3D.ready}/18`;
 document.getElementById('champion').innerHTML=u?`<strong>${kits[u.kit].icon} ${u.name} <span style="font:12px DM Sans;color:#bd9fe6">Lv ${u.level}</span></strong><div class="health"><i style="width:${u.hp/u.maxHp*100}%"></i></div><span>${Math.ceil(u.hp)} / ${u.maxHp} HP</span><div class="mana"><i style="width:${u.mana/u.maxMana*100}%"></i></div><span style="color:#ffd77c">🔔 ${u.bells} bells</span> <span style="float:right">${u.cs} CS · ${u.damage} AD</span><div class="xp"><i style="width:${u.xp/(u.level*140)*100}%"></i></div>`:'<strong>Spectating</strong>Choose a Conqueror to play';
 // Preserve the buttons while updating cooldowns, including during pointer clicks.
 if(abilityOwner!==u){
  abilityOwner=u;
  document.getElementById('abilities').innerHTML=u?kits[u.kit].skills.map((s,i)=>`<button class="ability" data-skill="${i}" title="${skillDescription(u.kit,i)}"><b>${'QWER'[i]} · ${['✦','◈','➶','♛'][i]}</b>${s}<small>${[35,55,45,100][i]} mana</small><span class="cd" style="display:none"></span></button>`).join(''):'<span style="padding:20px">Conquerors → choose your character</span>';
  abilityCooldowns=[];
  document.querySelectorAll('[data-skill]').forEach(b=>{b.onclick=()=>cast(selected,+b.dataset.skill,mouse);abilityCooldowns.push(b.querySelector('.cd'))});
 }
 if(u)abilityCooldowns.forEach((el,i)=>{el.style.display=u.skills[i]>0?'':'none';el.textContent=u.skills[i]>0?u.skills[i].toFixed(1):''});
 document.getElementById('hint').textContent=u?.recall>0?`Recalling… ${u.recall.toFixed(1)}s · movement cancels`:u?.cs>=3?'Farm bells, buy upgrades at base, and push behind your wave.':u?.cs>0?'Good last hit! Gold outlines mark minions your next attack can finish.':'Right-click a minion to attack. Time the last hit for bells. Q aims toward your cursor.';
 document.getElementById('target').innerHTML=hover&&hover.hp>0?`<b>${hover.name}</b> <span style="color:#cbd0a9">${Math.ceil(hover.hp)} / ${hover.maxHp} HP</span>${hover.kind==='hero'?'<br>Enemy Conqueror':''}`:'';document.getElementById('shop').textContent=flashCd>0?`B Recall · F Flash ${Math.ceil(flashCd)}s`:'Shop · B Recall · F Flash';};
function worldPoint(e){const r=canvas.getBoundingClientRect();return{x:camera.x+(e.clientX-r.left-r.width/2)/camera.zoom,y:camera.y+(e.clientY-r.top-r.height/2)/(camera.zoom*.83)}}
function command(p,target=null,attack=false){if(!selected||selected.hp<=0)return;if(target&&selected.order?.target===target)return;selected.recall=0;selected.pending=null;selected.navTimer=0;selected.order=target?{target}:{point:walkablePoint(p),attack};fx(p.x,p.y,16,target?'#efad80':'#91d9aa','ring',.4);tone(target?330:560,.03,'sine',.009)}
canvas.addEventListener('pointerdown',e=>{if(e.button===2){const p=worldPoint(e);const t=units.filter(u=>u.hp>0&&u.team!==selected?.team&&dist(u,p)<u.radius+18).sort((a,b)=>dist(a,p)-dist(b,p))[0]||null;command(p,t);attackMove=false}if(!audio){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio)audio=new Audio}audio?.resume()});
canvas.addEventListener('mousemove',e=>{Object.assign(mouse,worldPoint(e));hover=units.filter(u=>u.hp>0&&u.team!==selected?.team&&dist(u,mouse)<u.radius+15).sort((a,b)=>dist(a,mouse)-dist(b,mouse))[0]||null;if(e.buttons===2)command(mouse,hover)});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();const p=worldPoint(e);hover=units.filter(u=>u.hp>0&&u.team!==selected?.team&&dist(u,p)<u.radius+18).sort((a,b)=>dist(a,p)-dist(b,p))[0]||null;command(p,hover);attackMove=false});
canvas.addEventListener('click',e=>{if(attackMove){command(worldPoint(e),null,true);attackMove=false}else{const p=worldPoint(e);hover=units.find(u=>u.hp>0&&u.team!==selected?.team&&dist(u,p)<u.radius+15)||null}});
canvas.addEventListener('wheel',e=>{e.preventDefault();camera.zoom=clamp(camera.zoom*(e.deltaY>0?.93:1.07),.8,1.5)},{passive:false});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;const i=['KeyQ','KeyW','KeyE','KeyR'].indexOf(e.code);if(i>=0)cast(selected,i,mouse);if(e.code==='Space'&&selected){camera.x=selected.x;camera.y=selected.y;follow=true}if(e.code==='KeyY')follow=!follow;if(e.code==='KeyA')attackMove=true;if(e.code==='KeyS'&&selected){selected.order=null;selected.pending=null;selected.path=[];selected.recall=0}if(e.code==='KeyB'&&selected&&selected.hp>0){selected.order=null;selected.pending=null;selected.dash=null;selected.path=[];selected.navTimer=0;selected.recall=4}if(e.code==='KeyF'&&selected&&selected.hp>0&&winner===null&&flashCd<=0){const d=dist(selected,mouse)||1;const destination=walkablePoint({x:selected.x+(mouse.x-selected.x)/d*Math.min(250,d),y:selected.y+(mouse.y-selected.y)/d*Math.min(250,d)});fx(selected.x,selected.y,50,'#fff0ac');burst(selected.x,selected.y,'#fff0ac',20);Object.assign(selected,destination);selected.order=null;selected.pending=null;selected.recall=0;selected.path=[];selected.navDest=null;selected.navTimer=0;flashCd=25;fx(selected.x,selected.y,50,'#fff0ac');tone(950,.1,'sine',.04)}});
window.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('blur',()=>{keys.clear();attackMove=false});
document.addEventListener('visibilitychange',()=>{last=null;keys.clear();attackMove=false});
mini.onclick=e=>{const r=mini.getBoundingClientRect();camera.x=(e.clientX-r.left)/r.width*W;camera.y=(e.clientY-r.top)/r.height*H;follow=false};mini.oncontextmenu=e=>{e.preventDefault();const r=mini.getBoundingClientRect();command({x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H})};
document.getElementById('choose').onclick=()=>document.body.classList.toggle('roster-open');document.getElementById('watch').onclick=()=>{closeShop();selected=null;follow=false;camera.x=1600;camera.y=1600;camera.zoom=.85;document.body.classList.remove('roster-open');renderRoster();updateUI()};document.getElementById('pause').onclick=()=>{paused=!paused;document.getElementById('pause').textContent=paused?'Resume':'Pause'};document.getElementById('speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;document.getElementById('speed').textContent=speed+'× speed'};document.getElementById('reset').onclick=()=>{init();closeShop()};
function closeShop(){document.querySelector('.shop-panel')?.remove();shopOpen=false}
document.getElementById('shop').onclick=()=>{if(shopOpen){closeShop();return}if(!selected)return;const panel=document.createElement('div');panel.className='shop-panel';panel.innerHTML='<h3>Fountain armory</h3><p>Buy upgrades within your base. Press B to recall safely.</p><button data-buy="blade">Bellforged blade · 120 bells<br><small>+18 attack damage</small></button><button data-buy="armor">Barkplate armor · 100 bells<br><small>+200 maximum health</small></button><button data-buy="boots">Riverwalk boots · 80 bells<br><small>+25 movement speed</small></button><p id="shop-note"></p>';document.querySelector('.arena').appendChild(panel);shopOpen=true;panel.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const item=b.dataset.buy,cost={blade:120,armor:100,boots:80}[item],note=document.getElementById('shop-note');if(!selected||selected.hp<=0){note.textContent='Choose a living Conqueror before purchasing.';return}if(dist(selected,bases[selected.team])>260){note.textContent='Return to your fountain before purchasing.';return}if(selected.bells<cost){note.textContent=`You need ${cost-selected.bells} more bells.`;return}selected.bells-=cost;if(item==='blade')selected.damage+=18;if(item==='armor'){selected.maxHp+=200;selected.hp+=200}if(item==='boots')selected.speed+=25;note.textContent='Upgrade purchased.';tone(840,.15,'sine',.035);updateUI()})};
function frame(t){if(document.hidden){last=null;requestAnimationFrame(frame);return}const dt=last===null?0:Math.min(Math.max((t-last)/1000,0),.04);last=t;if(!paused)for(let i=0;i<speed;i++)update(dt);if(follow&&selected){camera.x+=(selected.x-camera.x)*Math.min(1,dt*12);camera.y+=(selected.y-camera.y)*Math.min(1,dt*12)}const pan=650*dt/camera.zoom;if(keys.has('ArrowLeft')){camera.x-=pan;follow=false}if(keys.has('ArrowRight')){camera.x+=pan;follow=false}if(keys.has('ArrowUp')){camera.y-=pan;follow=false}if(keys.has('ArrowDown')){camera.y+=pan;follow=false}camera.x=clamp(camera.x,120,W-120);camera.y=clamp(camera.y,120,H-120);draw();window.Minion3D?.render?.(units,camera,paused?0:dt*speed,projectiles);uiTimer+=dt;if(uiTimer>.1){updateUI();uiTimer=0}requestAnimationFrame(frame)}
init();requestAnimationFrame(frame);
